def semver_sort(versions):
    def parse_key(v):
        # split build metadata
        core = v.split('+', 1)[0]
        if '-' in core:
            idx = core.index('-')
            version_part = core[:idx]
            prerelease = core[idx+1:]
        else:
            version_part = core
            prerelease = None

        major, minor, patch = (int(x) for x in version_part.split('.'))

        if prerelease is None:
            has_pre = 1  # no prerelease sorts after
            pre_ids = []
        else:
            has_pre = 0
            ids = prerelease.split('.')
            pre_ids = []
            for ident in ids:
                if ident.isdigit():
                    pre_ids.append((0, int(ident)))
                else:
                    pre_ids.append((1, ident))

        return (major, minor, patch, has_pre, pre_ids)

    return sorted(versions, key=parse_key)

